// Connector icons (T2), drawn inline and shipped with the app: nothing is
// fetched from a vendor or a CDN at run time, so they work offline and under
// the CSP. Catalog entries name one in `icon` (`CATALOG_ICONS` in
// @openbot/mcp lists the names); a custom connector, or a brand whose logo we
// may not use, gets a lettermark from its name instead.
//
// Brand marks are the single-path SVGs from Simple Icons 16.36.0
// (https://simpleicons.org, CC0-1.0), copied as published. Firecrawl is not in
// Simple Icons and its brand page does not cover integrations, and Slack asked
// Simple Icons to remove its mark, so both use the lettermark. Everything
// renders in currentColor: one calm colour in both themes, where the black
// marks (GitHub, Vercel, Railway) would vanish in dark mode.

export type IconDef =
  /** A filled brand mark on a 24 by 24 grid. */
  | { kind: 'brand'; title: string; path: string }
  /** A stroked generic glyph on a 24 by 24 grid. */
  | { kind: 'glyph'; path: string };

