/** Every drawn icon; a catalog entry's `icon` names one of these or `lettermark`. */
export const CONNECTOR_ICONS: Readonly<Record<string, IconDef>> = { ...BRANDS, ...GLYPHS };

/** The drawn icon for a catalog `icon` name; null means draw a lettermark. */
export function resolveIcon(icon: string | null | undefined): IconDef | null {
  return (icon && Object.hasOwn(CONNECTOR_ICONS, icon) && CONNECTOR_ICONS[icon]) || null;
}

/** "Web search" is WS, "Firecrawl" is F, "my-server" is MS; a name with no letters gets the plug. */
export function lettermark(name: string): string {
  const words = name
    .replace(/\(.*?\)/g, ' ')
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean);
  return words
    .slice(0, 2)
    .map((w) => [...w][0]!.toUpperCase())
    .join('');
}

/**
 * A connector's icon in a small tile: the catalog's mark, or a lettermark
 * from the connector's own name. `sm` is the bare 14px mark for a line of
 * text, such as the transcript's tool activity.
 */
export function ConnectorIcon({
  icon,
  name,
  size = 'md',
  className,
}: {
  icon?: string | null;
  name: string;
  size?: 'sm' | 'md';
  className?: string;
}) {
  const def = resolveIcon(icon);
  const letters = def ? '' : lettermark(name);
  const shown = def ?? (letters ? null : GLYPHS.plug!);
  const md = size === 'md';
  return (
    <span
      aria-hidden
      data-icon={def ? icon : 'lettermark'}
      className={cn(
        'flex shrink-0 items-center justify-center text-foreground',
        md ? 'size-8 rounded-md border bg-muted' : 'size-3.5',
        className,
      )}
    >
      {shown ? (
        <svg
          viewBox="0 0 24 24"
          className={md ? 'size-4' : 'size-3.5'}
          {...(shown.kind === 'brand'
            ? { fill: 'currentColor' }
            : {
                fill: 'none',
                stroke: 'currentColor',
                strokeWidth: 2,
                strokeLinecap: 'round',
                strokeLinejoin: 'round',
              })}
        >
          <path d={shown.path} />
        </svg>
      ) : (
        <span
          className={cn(
            'font-semibold leading-none tracking-tight',
            md ? 'text-xs' : 'text-[9px] text-muted-foreground',
          )}
        >
          {letters}
        </span>
      )}
    </span>
  );
}
